#include <iostream>
#include <vector>
using namespace std;

int main() {   
    // Definizione del vettore di numeri
    vector<int> numeri = {12, 45, 7, 23, 56, 89, 34, 67, 5, 19};

    // Assumiamo che il primo elemento sia il massimo iniziale
    int massimo = numeri[0];

    // Ciclo per trovare il massimo nel vettore
    for (const auto& num : numeri) {
        if (num > massimo) {
            massimo = num;
        }
    }

    // Stampa del valore massimo trovato
    cout << "Il valore massimo nel vettore e': " << massimo << endl << endl;
    system("pause");
}
